  <div class="writer-control-actions"><a class="btn btn-primary" href="/admin/writers/<?=$writer['id']?>">التحكم الكامل</a><a class="btn btn-ghost" target="_blank" href="<?=e($public)?>">الملف العام</a></div>
 </article>
